import os
from openai import OpenAI
from typing import List, Dict, Any
from embeddings_models import EmbeddingRequest, EmbeddingResponse, BatchEmbeddingResponse

class EmbeddingsClient:
    def __init__(self, api_key: str = None):
        self.api_key = api_key or os.environ.get('OPENAI_API_KEY')
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY not found. Please provide it or set the environment variable.")
        self.client = OpenAI(api_key=self.api_key)

    def embed(self, texts: List[str], model: str = 'text-embedding-3-small') -> BatchEmbeddingResponse:
        # OpenAI API expects a single string or a list of strings for the 'input' parameter
        # If a single text is provided, wrap it in a list for consistency and then unwrap the result
        is_single_text = False
        if isinstance(texts, str):
            texts = [texts]
            is_single_text = True

        response = self.client.embeddings.create(model=model, input=texts)
        embeddings = [data.embedding for data in response.data]

        if is_single_text:
            return EmbeddingResponse(embedding=embeddings[0]) # Return a single embedding if single text was input
        return BatchEmbeddingResponse(embeddings=embeddings)

from typing import List, Dict, Any
from embeddings_client import EmbeddingsClient
from embeddings_models import BatchEmbeddingResponse

def embed_batch(payload: Dict[str, Any], config: Dict[str, Any] = None) -> Dict[str, List[List[float]]]:
    config = config or {}
    client = EmbeddingsClient(api_key=config.get('api_key'))

    texts = payload['texts']
    model = payload.get('model', 'text-embedding-3-small') # Default to the same model as embed_text.py

    response: BatchEmbeddingResponse = client.embed(texts=texts, model=model)
    return {'embeddings': response.embeddings}

import os
from typing import List, Dict, Any
from google.cloud import translate_v2 as translate # Provider-identifying signal: Google Cloud Translation API

def multilingual_query_translate(payload: Dict[str, Any], config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    queries = payload.get('queries', [])
    target_language = payload.get('target_language', 'en')

    # Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set for GCT API
    # Or provide credentials via config if not using environment variables.
    client = translate.Client()

    translated_queries = []
    for query in queries:
        result = client.translate(query, target_language=target_language)
        translated_queries.append({
            "original_query": query,
            "translated_query": result['translatedText'],
            "detected_source_language": result['detectedSourceLanguage']
        })

    return {"translated_queries": translated_queries}
